,\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/9/29/\",\"title\":\"TEXT 29\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2759,\"bb\":568235,\"url_path\":\"/en/library/bg/9/28/devanagari/\",\"body_final\":\"श‍ुभाश‍ुभफलैरेवं मोक्ष्यसे कर्मबन्धनै: ।
सन्न्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि ॥ २८ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2760,\"bb\":2442,\"url_path\":\"/en/library/bg/9/28/b2442/\",\"body_value\":\"śubhāśubha-phalair evaṁ
mokṣyase karma-bandhanaiḥ
sannyāsa-yoga-yuktātmā
vimukto mām upaiṣyasi\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2761,\"bb\":2443,\"url_path\":\"/en/library/bg/9/28/b2443/\",\"shadow_value\":\"śubha – from auspicious; aśubha – and inauspicious; phalaiḥ – results; evam – thus; mokṣyase – you will become free; karma – of work; bandhanaiḥ – from the bondage; sannyāsa – of renunciation; yoga – the yoga; yukta-ātmā – having the mind firmly set on; vimuktaḥ – liberated; mām – to Me; upaiṣyasi – you will attain.\",\"word_for_word_value\":[{\"word\":\"śubha\",\"translation\":\"from auspicious\"},{\"word\":\"aśubha\",\"translation\":\"and inauspicious\"},{\"word\":\"phalaiḥ\",\"translation\":\"results\"},{\"word\":\"evam\",\"translation\":\"thus\"},{\"word\":\"mokṣyase\",\"translation\":\"you will become free\"},{\"word\":\"karma\",\"translation\":\"of work\"},{\"word\":\"bandhanaiḥ\",\"translation\":\"from the bondage\"},{\"word\":\"sannyāsa\",\"translation\":\"of renunciation\"},{\"word\":\"yoga\",\"translation\":\"the yoga\"},{\"word\":\"yukta-ātmā\",\"translation\":\"having the mind firmly set on\"},{\"word\":\"vimuktaḥ\",\"translation\":\"liberated\"},{\"word\":\"mām\",\"translation\":\"to Me\"},{\"word\":\"upaiṣyasi\",\"translation\":\"you will attain\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2762,\"bb\":2444,\"url_path\":\"/en/library/bg/9/28/b2444/\",\"body_value\":\"In this way you will be freed from bondage to work and its auspicious and inauspicious results. With your mind fixed on Me in this principle of renunciation, you will be liberated and come to Me.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2763,\"bb\":2445,\"url_path\":\"/en/library/bg/9/28/b2445/\",\"body_value\":\"One who acts in Kṛṣṇa consciousness under superior direction is called yukta. The technical term is yukta-vairāgya. This is further explained by Rūpa Gosvāmī as follows:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2764,\"bb\":2446,\"url_path\":\"/en/library/bg/9/28/b2446/\",\"body_value\":\"anāsaktasya viṣayān
yathārham upayuñjataḥ
nirbandhaḥ kṛṣṇa-sambandhe
yuktaṁ vairāgyam ucyate\"},{\"type\":\"content.Record\",\"title\":\"reference\",\"id\":2765,\"bb\":2447,\"url_path\":\"/en/library/bg/9/28/b2447/\",\"body_value\":\"(Bhakti-rasāmṛta-sindhu, 1.2.255)\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2766,\"bb\":2448,\"url_path\":\"/en/library/bg/9/28/b2448/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2767,\"bb\":2449,\"url_path\":\"/en/library/bg/9/28/b2449/\",\"body_value\":\"Anyone who has no interest but to dedicate his life to the service of the Lord is actually a sannyāsī. Such a person always thinks of himself as an eternal servant, dependent on the supreme will of the Lord. As such, whatever he does, he does it for the benefit of the Lord. Whatever action he performs, he performs it as service to the Lord. He does not give serious attention to the fruitive activities or prescribed duties mentioned in the Vedas. For ordinary persons it is obligatory to execute the prescribed duties mentioned in the Vedas, but although a pure devotee who is completely engaged in the service of the Lord may sometimes appear to go against the prescribed Vedic duties, actually it is not so.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2768,\"bb\":2450,\"url_path\":\"/en/library/bg/9/28/b2450/\",\"body_value\":\"It is said, therefore, by Vaiṣṇava authorities that even the most intelligent person cannot understand the plans and activities of a pure devotee. The exact words are tāṅra vākya, kriyā, mudrā vijñeha nā bujhaya (Caitanya-caritāmṛta, Madhya 23.39). A person who is thus always engaged in the service of the Lord or is always thinking and planning how to serve the Lord is to be considered completely liberated at present, and in the future his going back home, back to Godhead, is guaranteed. He is above all materialistic criticism, just as Kṛṣṇa is above all criticism.\"}]}],\"short_title\":\"Bg. 9.28\",\"medium_title\":\"Bhagavad-gītā As It Is 9.28\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"Bhagavad-gītā As It Is\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/9/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/9/\",\"className\":\"text-vb-link\",\"children\":\"Chapter Nine: The Most Confidential Knowledge\"}],false]}]]}]}],[\"$\",\"main\",null,{\"children\":[\"$L29\",[\"$\",\"div\",null,{\"children\":[[\"$\",\"$L2a\",null,{\"child\":\"$23:props:children:0:props:children:props:page\",\"hasId\":false,\"isWhole